class QuantumTensorNetwork:
    def __init__(self, layers, tensor_shape, entanglement_rate=0.8, seed=None):
        if len(tensor_shape) != 2 or tensor_shape[0] != tensor_shape[1]:
            raise ValueError("tensor_shape must be a square 2D shape like (n, n)")
        self.rng = np.random.default_rng(seed)
        self.layers = int(layers)
        self.tensor_shape = tuple(tensor_shape)
        self.entanglement_rate = float(entanglement_rate)
        self.tensors = self._initialize_tensors()

    def _initialize_tensors(self):
        n = self.tensor_shape[0]
        tensors = []
        for _ in range(self.layers):
            real = self.rng.standard_normal((n, n))
            imag = self.rng.standard_normal((n, n))
            t = (real + 1j * imag) / np.sqrt(2.0 * n)
            tensors.append(t.astype(np.complex128))
        return tensors

    def entangle_tensors(self):
        n = self.tensor_shape[0]
        for i in range(self.layers - 1):
            if self.rng.random() < self.entanglement_rate:
                a = self.rng.standard_normal((n, n))
                q, _ = np.linalg.qr(a)
                self.tensors[i] = self.tensors[i] @ q
                self.tensors[i + 1] = q.conj().T @ self.tensors[i + 1]

    def contract_tensors(self):
        result = self.tensors[0]
        for i in range(1, self.layers):
            result = result @ self.tensors[i]
        return result

    def propagate(self, input_data):
        v = np.asarray(input_data, dtype=np.complex128)
        if v.ndim != 1 or v.shape[0] != self.tensor_shape[0]:
            raise ValueError("input_data must be a vector with length matching tensor dimension")
        for t in self.tensors:
            v = v @ t
            v = self._complex_phase_modulation(v)
        return v

    def _complex_phase_modulation(self, tensor):
        phase = self.rng.random(tensor.shape) * 2.0 * np.pi
        return tensor * np.exp(1j * phase)


class HyperdimensionalComputing:
    def __init__(self, dimension, seed=None):
        self.rng = np.random.default_rng(seed)
        self.dimension = int(dimension)
        self.item_memory = {}

    def generate_hv(self, item):
        if item in self.item_memory:
            return self.item_memory[item]
        hv = self.rng.choice([-1, 1], size=self.dimension).astype(np.int8)
        self.item_memory[item] = hv
        return hv

    def bundle(self, hvs):
        if len(hvs) == 0:
            raise ValueError("hvs must be non-empty")
        return np.sum(np.stack(hvs, axis=0), axis=0)

    def bind(self, hv1, hv2):
        f1 = np.fft.fft(hv1)
        f2 = np.fft.fft(hv2)
        return np.fft.ifft(f1 * f2).real

    def unbind(self, bundled_hv, hv_to_remove):
        f1 = np.fft.fft(bundled_hv)
        f2 = np.fft.fft(hv_to_remove)
        eps = 1e-12
        return np.fft.ifft(f1 / (f2 + eps)).real

    def similarity(self, hv1, hv2):
        hv1 = np.asarray(hv1)
        hv2 = np.asarray(hv2)
        n1 = np.linalg.norm(hv1)
        n2 = np.linalg.norm(hv2)
        if n1 == 0 or n2 == 0:
            return 0.0
        return float(np.dot(hv1, hv2) / (n1 * n2))

    def cleanup(self, hv, threshold=0.1):
        best_item = None
        best_sim = -1.0
        for item, stored_hv in self.item_memory.items():
            s = self.similarity(hv, stored_hv)
            if s > best_sim and s > threshold:
                best_sim = s
                best_item = item
        return best_item


class NeuromorphicProcessor:
    def __init__(self, cores, synaptic_density, seed=None):
        self.rng = np.random.default_rng(seed)
        self.cores = int(cores)
        self.synaptic_density = int(synaptic_density)
        self.neurons = self.rng.random((self.cores, self.synaptic_density))
        self.synapses = self.rng.random((self.cores, self.synaptic_density, self.synaptic_density))

    def spike(self, input_signal):
        x = np.asarray(input_signal, dtype=float)
        if x.shape != (self.synaptic_density,):
            raise ValueError("input_signal shape mismatch")
        voltages = np.sum(self.neurons * x[None, :], axis=1)
        thr = self.rng.random(self.cores)
        spikes = voltages > thr
        return spikes

    def synaptic_transmission(self, spikes):
        spikes = np.asarray(spikes, dtype=bool)
        if spikes.shape != (self.cores,):
            raise ValueError("spikes shape mismatch")
        transmitted_signals = np.zeros_like(self.neurons)
        for core in range(self.cores):
            if spikes[core]:
                transmitted_signals[core] = np.sum(self.synapses[core] * self.neurons[core][:, None], axis=0)
        return transmitted_signals

    def learn(self, input_signal, reward):
        x = np.asarray(input_signal, dtype=float)
        if x.shape != (self.synaptic_density,):
            raise ValueError("input_signal shape mismatch")
        r = float(reward)
        for core in range(self.cores):
            self.synapses[core] += r * np.outer(x, self.neurons[core])


