    def __init__(self, nodes, feedback_strength, nonlinearity, seed=None):
        self.rng = np.random.default_rng(seed)
        self.nodes = int(nodes)
        self.feedback_strength = float(feedback_strength)
        self.nonlinearity = float(nonlinearity)
        self.state = self.rng.random(self.nodes)

    def evolve(self, input_signal):
        if np.isscalar(input_signal):
            inp = float(input_signal)
        else:
            arr = np.asarray(input_signal, dtype=float).ravel()
            inp = float(arr.mean()) if arr.size > 0 else 0.0
        self.state = np.tanh(self.feedback_strength * self.state + self.nonlinearity * (self.state + inp))
        return self.state


class ActiveInferenceEngine:
    def __init__(self, states, actions, observations, prior_precision, likelihood_precision, transition_precision, seed=None):
        self.rng = np.random.default_rng(seed)
        self.states = int(states)
        self.actions = int(actions)
        self.observations = int(observations)
        self.prior = self._normalize(self.rng.random(self.states) + 1e-6)
        self.likelihood = self._normalize(self.rng.random((self.states, self.observations)) + 1e-6, axis=0)
        self.transition = self._normalize(self.rng.random((self.states, self.actions, self.states)) + 1e-6, axis=2)
        self.prior_precision = float(prior_precision)
        self.likelihood_precision = float(likelihood_precision)
        self.transition_precision = float(transition_precision)

    def _normalize(self, x, axis=None):
        x = np.asarray(x, dtype=float)
        if axis is None:
            s = x.sum()
            if s <= 0:
                return np.full_like(x, 1.0 / x.size)
            return x / s
        s = x.sum(axis=axis, keepdims=True)
        s[s <= 0] = 1.0
        return x / s

    def infer(self, observation, action):
        o = int(observation)
        a = int(action)
        pred = self.transition[:, a, :].T @ self.prior
        post = pred * self.likelihood[:, o]
        post = self._normalize(post)
        self.prior = post
        return post

    def learn(self, observation, action, reward):
        o = int(observation)
        a = int(action)
        r = float(reward)
        pred_obs = float(self.prior @ self.likelihood[:, o])
        pe = r - pred_obs
        self.likelihood[:, o] = self._normalize(self.likelihood[:, o] + self.likelihood_precision * pe * self.prior)
        self.transition[:, a, :] = self._normalize(self.transition[:, a, :] + self.transition_precision * pe * np.outer(self.prior, self.prior), axis=1)
        self.prior = self._normalize(self.prior + self.prior_precision * pe * self.prior)


class BiologicallyPlausibleTokenizer:
    def __init__(self, vocabulary_size, embedding_dimension, seed=None):
        self.rng = np.random.default_rng(seed)
        self.vocabulary_size = int(vocabulary_size)
        self.embedding_dimension = int(embedding_dimension)
        self.embeddings = self.rng.random((self.vocabulary_size, self.embedding_dimension))
        self.word_to_index = {"<unk>": 0}
        self.index_to_word = {0: "<unk>"}

    def build_vocabulary(self, texts):
        tokens = []
        for t in texts:
            tokens.extend(str(t).split())
        unique = sorted(list(set(tokens)))
        limit = min(self.vocabulary_size - 1, len(unique))
        for i in range(limit):
            w = unique[i]
            idx = i + 1
            self.word_to_index[w] = idx
            self.index_to_word[idx] = w

    def tokenize(self, text):
        words = str(text).split()
        return [self.word_to_index.get(w, 0) for w in words]

    def detokenize(self, tokens):
        return " ".join([self.index_to_word.get(int(t), "<unk>") for t in tokens])

    def embed(self, tokens):
        idx = np.asarray(tokens, dtype=int)
        idx[idx < 0] = 0
        idx[idx >= self.vocabulary_size] = 0
        return self.embeddings[idx]


class AdiabaticQuantumOptimizer:
    def __init__(self, num_variables, coupling_strength, seed=None):
        self.rng = np.random.default_rng(seed)
        self.num_variables = int(num_variables)
        self.coupling_strength = float(coupling_strength)
        self.qubits = self.rng.random(self.num_variables)

    def evolve(self, hamiltonian, annealing_time):
        h = np.asarray(hamiltonian, dtype=float)
        if h.shape != (self.num_variables,):
            raise ValueError("hamiltonian shape mismatch")
        T = float(annealing_time)
        for t in np.linspace(0.0, T, 128):
            grad = h
            self.qubits -= self.coupling_strength * grad * (t / T if T > 0 else 0.0)
            self.qubits = np.clip(self.qubits, 0.0, 1.0)
        return self.qubits


class SelfOrganizingDataPipeline:
    def __init__(self, input_shape, output_shape, mutation_rate=0.01, seed=None):
        self.rng = np.random.default_rng(seed)
        self.input_shape = tuple(input_shape)
        self.output_shape = tuple(output_shape)
        self.mutation_rate = float(mutation_rate)
        self.pipeline = self._initialize_pipeline()

    def _initialize_pipeline(self):
        input_size = int(np.prod(self.input_shape))
        output_size = int(np.prod(self.output_shape))
        hidden_size = max(8, (input_size + output_size) // 2)
        w1 = self.rng.standard_normal((input_size, hidden_size)) / np.sqrt(input_size)
        w2 = self.rng.standard_normal((hidden_size, output_size)) / np.sqrt(hidden_size)
        return [w1, w2]

    def process(self, data):
        x = np.asarray(data, dtype=float).reshape(-1)
        a = x @ self.pipeline[0]
        a = np.tanh(a)
        y = a @ self.pipeline[1]
        return y.reshape(self.output_shape)

    def evolve(self, fitness_function, data):
        baseline = float(fitness_function(self.process(data)))
        mutated = [w + self.rng.standard_normal(w.shape) * self.mutation_rate for w in self.pipeline]
        old_pipeline = self.pipeline
        self.pipeline = mutated
        mutated_score = float(fitness_function(self.process(data)))
        if mutated_score <= baseline:
            self.pipeline = old_pipeline


