class QuantumResistantCryptography:
    def __init__(self):
        pass

    def generate_keypair(self):
        private_key = x25519.X25519PrivateKey.generate()
        public_key = private_key.public_key()
        return private_key, public_key

    def export_public_key(self, public_key):
        return public_key.public_bytes(encoding=serialization.Encoding.Raw, format=serialization.PublicFormat.Raw)

    def import_public_key(self, public_key_bytes):
        return x25519.X25519PublicKey.from_public_bytes(public_key_bytes)

    def encrypt(self, data, recipient_public_key):
        if isinstance(recipient_public_key, bytes):
            recipient_public_key = self.import_public_key(recipient_public_key)
        eph_priv = x25519.X25519PrivateKey.generate()
        eph_pub = eph_priv.public_key()
        shared = eph_priv.exchange(recipient_public_key)
        hkdf = HKDF(algorithm=hashes.SHA256(), length=32, salt=None, info=b"x25519-chacha20poly1305")
        key = hkdf.derive(shared)
        aead = ChaCha20Poly1305(key)
        nonce = os.urandom(12)
        ct = aead.encrypt(nonce, data, None)
        eph_pub_bytes = self.export_public_key(eph_pub)
        return eph_pub_bytes + nonce + ct

    def decrypt(self, ciphertext, recipient_private_key):
        eph_pub_bytes = ciphertext[:32]
        nonce = ciphertext[32:44]
        ct = ciphertext[44:]
        eph_pub = x25519.X25519PublicKey.from_public_bytes(eph_pub_bytes)
        shared = recipient_private_key.exchange(eph_pub)
        hkdf = HKDF(algorithm=hashes.SHA256(), length=32, salt=None, info=b"x25519-chacha20poly1305")
        key = hkdf.derive(shared)
        aead = ChaCha20Poly1305(key)
        pt = aead.decrypt(nonce, ct, None)
        return pt


