class RobustErrorCorrection:
    def __init__(self):
        pass

    def encode(self, data):
        b = bytes(data)
        out = bytearray()
        for byte in b:
            out.extend([byte, byte, byte])
        return bytes(out)

    def decode(self, encoded_data):
        b = bytes(encoded_data)
        if len(b) % 3 != 0:
            raise ValueError("encoded_data length invalid")
        out = bytearray()
        for i in range(0, len(b), 3):
            a, c, d = b[i], b[i + 1], b[i + 2]
            if a == c or a == d:
                out.append(a)
            elif c == d:
                out.append(c)
            else:
                out.append(a)
        return bytes(out)


